// Builds the Apps Script backend files from backend/src and backend/seed.
//
//   node tools/build_apps_script.mjs
//
// Apps Script cannot load ES modules, so this script wraps each module in a
// function and joins them into one file. The result is:
//   backend/apps-script/Bundle.gs    - all portal actions (from backend/src)
//   backend/apps-script/SeedData.gs  - the FAKE test data (from backend/seed/seed-data.json),
//                                      used by setupSheets() on a TEST spreadsheet
// Do not edit those two files by hand; edit the sources and run this again.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, resolve, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const jsRoot = resolve(root, 'backend/src');
const seedFile = resolve(root, 'backend/seed/seed-data.json');
const outDir = resolve(root, 'backend/apps-script');

// Modules the server needs: the action table, plus helpers Server.gs uses.
const ENTRIES = ['actions.js', 'utils.js', 'config.js'];

const IMPORT_RE = /import\s+([\s\S]*?)\s+from\s+['"](.+?)['"];?/g;
const EXPORT_DECL_RE = /^export\s+(async\s+function|function|const|let|class)\s+([A-Za-z_$][\w$]*)/gm;

const modules = new Map(); // id -> { id, code, deps }
const order = [];

function idOf(file) {
  return relative(jsRoot, file).replaceAll('\\', '/').replace(/\.js$/, '');
}

function load(file) {
  const id = idOf(file);
  if (modules.has(id)) return id;
  modules.set(id, null); // mark as in progress (no import cycles expected)

  let code = readFileSync(file, 'utf8');
  const deps = [];
  code = code.replace(IMPORT_RE, (_, clause, spec) => {
    const depId = load(resolve(dirname(file), spec));
    deps.push(depId);
    const mod = `__m[${JSON.stringify(depId)}]`;
    clause = clause.trim();
    if (clause.startsWith('* as ')) return `const ${clause.slice(5).trim()} = ${mod};`;
    if (clause.startsWith('{')) {
      const names = clause.slice(1, -1).split(',').map((s) => s.trim()).filter(Boolean)
        .map((s) => s.replace(/\s+as\s+/, ': '));
      return `const { ${names.join(', ')} } = ${mod};`;
    }
    throw new Error(`Unsupported import in ${id}: ${clause}`);
  });

  const exported = [];
  code = code.replace(EXPORT_DECL_RE, (_, kind, name) => {
    exported.push(name);
    return `${kind} ${name}`;
  });
  if (/^export\s/m.test(code)) throw new Error(`Unsupported export form in ${id}`);

  modules.set(id, { id, code, exported });
  order.push(id);
  return id;
}

ENTRIES.forEach((entry) => load(resolve(jsRoot, entry)));

const indent = (text) => text.trimEnd().split('\n').map((line) => (line ? `    ${line}` : line)).join('\n');
const header = `// GENERATED by tools/build_apps_script.mjs on ${new Date().toISOString().slice(0, 10)}. Do not edit by hand.
// Source: backend/src (${ENTRIES.join(', ')} and what they import).
`;

const bundle = `${header}
var RFID = (function () {
  'use strict';
  const __m = {};
${order.map((id) => {
  const mod = modules.get(id);
  return `
  // ---- ${id}.js ----
  __m[${JSON.stringify(id)}] = (function () {
${indent(mod.code)}
    return { ${mod.exported.join(', ')} };
  })();`;
}).join('\n')}

  return Object.assign({}, __m['config'], __m['utils'], __m['actions']);
})();
`;

// Apps Script's JavaScript engine understands ES2020, not newer syntax.
// Stop here instead of producing a file that fails to save in the editor.
const TOO_NEW = [
  [/\b\d+_\d+/, 'numeric separator like 60_000 (write 60000)'],
  [/(\?\?|\|\||&&)=/, 'logical assignment like ??= (write a = a ?? b)'],
  [/\.replaceAll\(/, '.replaceAll() (use .replace(/x/g, ...))'],
  [/\.at\(-?\d/, '.at() (use [index])'],
];
bundle.split('\n').forEach((line, i) => {
  TOO_NEW.forEach(([pattern, what]) => {
    if (pattern.test(line)) throw new Error(`Bundle.gs line ${i + 1}: ${what}\n  ${line.trim()}`);
  });
});

mkdirSync(outDir, { recursive: true });
writeFileSync(resolve(outDir, 'Bundle.gs'), bundle);

// Seed data: FAKE test records only, for a TEST spreadsheet.
const seed = JSON.parse(readFileSync(seedFile, 'utf8'));
writeFileSync(resolve(outDir, 'SeedData.gs'), `// GENERATED by tools/build_apps_script.mjs on ${new Date().toISOString().slice(0, 10)}. Do not edit by hand.
// Source: backend/seed/seed-data.json. FAKE test data only, loaded into empty tabs by setupSheets().
var SEED_DATA = ${JSON.stringify(seed, null, 1)};
`);

console.log(`Wrote backend/apps-script/Bundle.gs (${order.length} modules: ${order.join(', ')})`);
console.log('Wrote backend/apps-script/SeedData.gs');
